{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "additionalProperties": false,
    "name": "Repository Configuration",
    "properties": {
        "abandoned": {
            "additionalProperties": {
                "description": "A valid Package name",
                "type": [
                    "boolean",
                    "string"
                ]
            },
            "description": "List of packages marked as abandoned for this repository, the mark can be boolean or a package name/URL pointing to a recommended alternative.",
            "type": "object"
        },
        "archive": {
            "additionalProperties": false,
            "description": "Options for creating package archives for distribution.",
            "properties": {
                "absolute-directory": {
                    "description": "The absolute path of the dist files.",
                    "type": "string"
                },
                "blacklist": {
                    "description": "List of blacklisted packages.",
                    "items": {
                        "type": "string"
                    },
                    "type": "array"
                },
                "checksum": {
                    "description": "If false, will not provide the sha1 checksum for the dist files.",
                    "type": "boolean"
                },
                "directory": {
                    "description": "The location of the dist files.",
                    "type": "string"
                },
                "format": {
                    "description": "Archive format.",
                    "pattern": "^zip|tar$",
                    "type": "string"
                },
                "prefix-url": {
                    "_format": "uri",
                    "description": "Location of the downloads.",
                    "type": "string"
                },
                "skip-dev": {
                    "description": "If true, will not create downloads for branches.",
                    "type": "boolean"
                },
                "whitelist": {
                    "description": "List of whitelisted packages.",
                    "items": {
                        "type": "string"
                    },
                    "type": "array"
                }
            },
            "required": [
                "directory"
            ],
            "type": "object"
        },
        "config": {
            "description": "Composer options.",
            "properties": {
                "autoloader-suffix": {
                    "description": "Optional string to be used as a suffix for the generated Composer autoloader. When null a random one will be generated.",
                    "type": "string"
                },
                "bin-compat": {
                    "description": "The compatibility of the binaries, defaults to \"auto\" (automatically guessed) and can be \"full\" (compatible with both Windows and Unix-based systems).",
                    "enum": [
                        "auto",
                        "full"
                    ]
                },
                "bin-dir": {
                    "description": "The location where all binaries are linked, defaults to \"vendor/bin\".",
                    "type": "string"
                },
                "cache-dir": {
                    "description": "The location where all caches are located, defaults to \"~/.composer/cache\" on *nix and \"%LOCALAPPDATA%\\Composer\" on windows.",
                    "type": "string"
                },
                "cache-files-dir": {
                    "description": "The location where files (zip downloads) are cached, defaults to \"{$cache-dir}/files\".",
                    "type": "string"
                },
                "cache-files-maxsize": {
                    "description": "The cache max size for the files cache, defaults to \"300MiB\".",
                    "type": [
                        "string",
                        "integer"
                    ]
                },
                "cache-files-ttl": {
                    "description": "The cache time-to-live for files, defaults to the value of cache-ttl.",
                    "type": "integer"
                },
                "cache-repo-dir": {
                    "description": "The location where repo (git/hg repo clones) are cached, defaults to \"{$cache-dir}/repo\".",
                    "type": "string"
                },
                "cache-ttl": {
                    "description": "The default cache time-to-live, defaults to 15552000 (6 months).",
                    "type": "integer"
                },
                "cache-vcs-dir": {
                    "description": "The location where vcs infos (git clones, github api calls, etc. when reading vcs repos) are cached, defaults to \"{$cache-dir}/vcs\".",
                    "type": "string"
                },
                "classmap-authoritative": {
                    "description": "If true, the composer autoloader will not scan the filesystem for classes that are not found in the class map, defaults to false.",
                    "type": "boolean"
                },
                "discard-changes": {
                    "description": "The default style of handling dirty updates, defaults to false and can be any of true, false or \"stash\".",
                    "type": [
                        "string",
                        "boolean"
                    ]
                },
                "github-domains": {
                    "description": "A list of domains to use in github mode. This is used for GitHub Enterprise setups, defaults to [\"github.com\"].",
                    "items": {
                        "type": "string"
                    },
                    "type": "array"
                },
                "github-expose-hostname": {
                    "description": "Defaults to true. If set to false, the OAuth tokens created to access the github API will have a date instead of the machine hostname.",
                    "type": "boolean"
                },
                "github-oauth": {
                    "additionalProperties": true,
                    "description": "A hash of domain name => github API oauth tokens, typically {\"github.com\":\"<token>\"}.",
                    "type": "object"
                },
                "github-protocols": {
                    "description": "A list of protocols to use for github.com clones, in priority order, defaults to [\"git\", \"https\", \"http\"].",
                    "items": {
                        "type": "string"
                    },
                    "type": "array"
                },
                "http-basic": {
                    "additionalProperties": true,
                    "description": "A hash of domain name => {\"username\": \"...\", \"password\": \"...\"}.",
                    "type": "object"
                },
                "notify-on-install": {
                    "description": "Composer allows repositories to define a notification URL, so that they get notified whenever a package from that repository is installed. This option allows you to disable that behaviour, defaults to true.",
                    "type": "boolean"
                },
                "optimize-autoloader": {
                    "description": "Always optimize when dumping the autoloader.",
                    "type": "boolean"
                },
                "platform": {
                    "additionalProperties": true,
                    "description": "This is a hash of package name (keys) and version (values) that will be used to mock the platform packages on this machine.",
                    "type": "object"
                },
                "preferred-install": {
                    "description": "The install method Composer will prefer to use, defaults to auto and can be any of source, dist or auto.",
                    "type": "string"
                },
                "prepend-autoloader": {
                    "description": "If false, the composer autoloader will not be prepended to existing autoloaders, defaults to true.",
                    "type": "boolean"
                },
                "process-timeout": {
                    "description": "The timeout in seconds for process executions, defaults to 300 (5mins).",
                    "type": "integer"
                },
                "store-auths": {
                    "description": "What to do after prompting for authentication, one of: true (store), false (do not store) or \"prompt\" (ask every time), defaults to prompt.",
                    "type": [
                        "string",
                        "boolean"
                    ]
                },
                "use-include-path": {
                    "description": "If true, the Composer autoloader will also look for classes in the PHP include path.",
                    "type": "boolean"
                },
                "vendor-dir": {
                    "description": "The location where all packages are installed, defaults to \"vendor\".",
                    "type": "string"
                }
            },
            "type": "object"
        },
        "description": {
            "description": "Short Repository description.",
            "type": "string"
        },
        "homepage": {
            "_format": "uri",
            "description": "Homepage URL for the Repository.",
            "type": "string"
        },
        "minimum-stability": {
            "description": "The minimum stability the packages must have to be install-able. Possible values are: dev, alpha, beta, RC, stable.",
            "enum": [
                "dev",
                "alpha",
                "beta",
                "rc",
                "RC",
                "stable"
            ],
            "type": [
                "string"
            ]
        },
        "name": {
            "description": "Repository name.",
            "type": "string"
        },
        "notify-batch": {
            "description": "a URL that will be called every time a user installs a package.",
            "type": "string"
        },
        "output-dir": {
            "description": "The directory where the static Repository is built.",
            "type": "string"
        },
        "output-html": {
            "description": "If true, build a static web page.",
            "type": "boolean"
        },
        "repositories": {
            "additionalProperties": true,
            "description": "A set of additional repositories where packages can be found.",
            "type": [
                "object",
                "array"
            ]
        },
        "require": {
            "additionalProperties": {
                "description": "A valid version constraint",
                "type": "string"
            },
            "description": "This is a hash of package name (keys) and version constraints (values) that are required to run this package.",
            "minProperties": 1,
            "type": "object"
        },
        "require-all": {
            "description": "If true, selects all versions of all packages in the repositories defined.",
            "type": "boolean"
        },
        "require-dependencies": {
            "description": "If true, resolve and add all dependencies of each required package.",
            "type": "boolean"
        },
        "require-dev-dependencies": {
            "description": "If true, resolve and add all Dev dependencies of each required package.",
            "type": "boolean"
        },
        "twig-template": {
            "description": "Path to a template for the static web page.",
            "type": "string"
        }
    },
    "required": [
        "name",
        "homepage"
    ],
    "type": "object"
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "definitions": {
        "interface": {
            "type": "object",
            "title": "Interface Specification",
            "properties": {
                "type": {
                    "type": "string",
                    "description": "Network interface type.",
                    "enum": [
                        "monitor",
                        "vlan",
                        "wifi-ap"
                    ]
                },
                "dhcp": {
                    "type": "object",
                    "properties": {
                        "leasetime": {
                            "type": "string",
                            "description": "Duration of client leases, e.g. 2h.",
                            "pattern": "\\d+[dhms]"
                        },
                        "limit": {
                            "type": "integer",
                            "description": "Size of address range beginning at start value.",
                            "minimum": 1
                        },
                        "start": {
                            "type": "integer",
                            "description": "Starting offset for address assignment.",
                            "minimum": 3
                        }
                    },
                    "additionalProperties": false
                },
                "dns": {
                    "type": "array",
                    "description": "List of DNS servers to advertise to connected clients.",
                    "items": {
                        "type": "string"
                    }
                },
                "wireless": {
                    "type": "object",
                    "properties": {
                        "ssid": {
                            "type": "string",
                            "description": "ESSID to broadcast.",
                            "maxLength": 32
                        },
                        "key": {
                            "type": "string",
                            "description": "Wireless network password.",
                            "minLength": 8
                        },
                        "nasid": {
                            "type": "string",
                            "description": "NAS identifier for RADIUS."
                        },
                        "acct_server": {
                            "type": "string",
                            "description": "RADIUS accounting server."
                        },
                        "acct_secret": {
                            "type": "string",
                            "description": "RADIUS accounting secret."
                        },
                        "acct_interval": {
                            "type": "integer",
                            "description": "RADIUS accounting update interval (seconds).",
                            "minimum": 1
                        },
                        "hidden": {
                            "type": "boolean",
                            "description": "Disable broadcasting the ESSID in beacons."
                        },
                        "isolate": {
                            "type": "boolean",
                            "description": "Disable forwarding traffic between connected clients."
                        },
                        "maxassoc": {
                            "type": "integer",
                            "description": "Maximum number of associated clients.",
                            "minimum": 0
                        }
                    },
                    "additionalProperties": false
                },
                "requirements": {
                    "type": "object",
                    "properties": {
                        "hwmode": {
                            "type": "string",
                            "description": "Required operating mode (11b for old hardware, 11g for 2.4 GHz, 11a for 5 Ghz).",
                            "enum": [
                                "11b",
                                "11g",
                                "11a"
                            ]
                        },
                        "ipv4_network": {
                            "type": "string",
                            "description": "Required IP network in slash notation.",
                            "pattern": "^\\d+\\.\\d+\\.\\d+\\.\\d+/\\d+"
                        }
                    },
                    "additionalProperties": false
                },
                "l3bridge": {
                    "type": "string",
                    "description": "Bridge to another network using ARP proxying (experimental)."
                },
                "vlan-id": {
                    "type": "integer",
                    "description": "VLAN tag for traffic to and from the interface.",
                    "minimum": 1,
                    "maximum": 4094
                }
            },
            "required": [
                "type"
            ],
            "additionalProperties": false,
            "$$target": "#/definitions/interface"
        },
        "service": {
            "type": "object",
            "title": "Service Specification",
            "properties": {
                "type": {
                    "type": "string",
                    "description": "Type of chute service.",
                    "enum": [
                        "light",
                        "normal",
                        "image"
                    ]
                },
                "source": {
                    "type": "string",
                    "description": "Source directory for this service."
                },
                "image": {
                    "type": "string",
                    "description": "Image specification for services that pull a Docker image."
                },
                "command": {
                    "anyOf": [
                        {
                            "type": "string"
                        },
                        {
                            "type": "array",
                            "items": {
                                "type": "string"
                            }
                        }
                    ]
                },
                "dns": {
                    "type": "array",
                    "description": "List of DNS servers to be used within the container.",
                    "items": {
                        "type": "string"
                    }
                },
                "environment": {
                    "type": "object",
                    "description": "Environment variables."
                },
                "interfaces": {
                    "type": "object",
                    "description": "Network interfaces to be connected.",
                    "patternProperties": {
                        "\\w{1,16}": {
                            "$ref": "#/definitions/interface"
                        }
                    }
                },
                "requests": {
                    "type": "object",
                    "properties": {
                        "as-root": {
                            "type": "boolean",
                            "description": "Run service as privileged user."
                        },
                        "port-bindings": {
                            "type": "array",
                            "description": "Port bindings from host to service container.",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "external": {
                                        "type": "integer",
                                        "description": "External (host) port number.",
                                        "minimum": 1,
                                        "maximum": 65536
                                    },
                                    "internal": {
                                        "type": "integer",
                                        "description": "Internal (container) port number.",
                                        "minimum": 1,
                                        "maximum": 65536
                                    }
                                },
                                "additionalProperties": false
                            }
                        }
                    },
                    "additionalProperties": false
                }
            },
            "additionalProperties": false,
            "$$target": "#/definitions/service"
        }
    },
    "type": "object",
    "title": "Chute Specification",
    "properties": {
        "name": {
            "type": "string",
            "description": "Name of the chute."
        },
        "description": {
            "type": "string",
            "description": "Description of the chute to be shown to users."
        },
        "version": {
            "description": "Version of the chute.",
            "anyOf": [
                {
                    "type": "string"
                },
                {
                    "type": "number"
                }
            ]
        },
        "services": {
            "type": "object",
            "description": "Services to be installed with the chute.",
            "patternProperties": {
                "\\w+": {
                    "$ref": "#/definitions/service"
                }
            }
        },
        "web": {
            "type": "object",
            "properties": {
                "service": {
                    "type": "string",
                    "description": "Name of chute service which provides the web service."
                },
                "port": {
                    "type": "integer",
                    "description": "Listening port inside the chute.",
                    "minimum": 1,
                    "maximum": 65536
                }
            },
            "additionalProperties": false
        }
    },
    "required": [
        "name"
    ],
    "additionalProperties": false
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "title": "OSVR Display Descriptor (v1)",
  "description": "This schema documents and guides creation of a display descriptor, that describes properties of a head-mounted display",
  "type": "object",
  "properties": {
    "meta": {
      "title": "JSON Schema metadata",
      "description": "Details about the JSON display descriptor schema.",
      "type": "object",
      "properties": {
        "schemaVersion": {
          "title": "Schema Version",
          "description": "Version number of the display descriptor JSON schema. If you're using this schema, the value should be 1",
          "type": "number",
          "default": 1
        }
      }
    },
    "hmd": {
      "title": "HMD",
      "description": "Properties of a head-mounted display.",
      "type": "object",
      "properties": {
        "device": {
          "title": "HMD Device Description",
          "description": "Describes HMD hardware and metadata.",
          "type": "object",
          "properties": {
            "vendor": {
              "title": "Device vendor/manufacturer",
              "type": "string"
            },
            "model": {
              "title": "Device model",
              "type": "string"
            },
            "Version": {
              "title": "Device version",
              "type": "string"
            },
            "num_displays": {
              "title": "Number of physical screens (NOT USED)",
              "description": "This is redundant with information elsewhere in the schema and should not be used.",
              "type": "integer",
              "default": 1
            },
            "Note": {
              "title": "Notes about the device",
              "type": "string"
            }
          },
          "required": [
            "vendor",
            "model"
          ]
        },
        "field_of_view": {
          "title": "HMD Field of View Description",
          "description": "Defines the optical parameters of the HMD. Since some HMDs have partial overlap – meaning that the viewing direction of the left and right eye are not identical – we define the field of view of just one eye and then the overlap between them.",
          "type": "object",
          "properties": {
            "monocular_horizontal": {
              "title": "Monocular Horizontal FOV in degrees",
              "type": "number"
            },
            "monocular_vertical": {
              "title": "Monocular Vertical FOV in degrees",
              "type": "number"
            },
            "overlap_percent": {
              "title": "Percentage of horizontal FOV that is 'overlapped'.",
              "type": "number"
            },
            "pitch_tilt": {
              "title": "Pitch tilt in degrees (NOT HANDLED)",
              "description": "Some HMDs have their field of view tilted downwards. In this case, pitch_tilt would have a non-zero value in degrees, where positive is a downward tilt.",
              "type": "number",
              "default": 0
            }
          },
          "required": [
            "monocular_horizontal",
            "monocular_vertical",
            "overlap_percent"
          ]
        },
        "resolutions": {
          "title": "Supported resolutions",
          "type": "array",
          "minItems": 1,
          "maxItems": 1,
          "items": {
            "title": "HMD Resolution Description",
            "description": "Describes HMD properties related to resolution.",
            "type": "object",
            "properties": {
              "width": {
                "title": "Horizontal size, in pixels, of a video input.",
                "type": "integer"
              },
              "height": {
                "title": "Vertical size, in pixels, of a video input.",
                "type": "integer"
              },
              "video_inputs": {
                "title": "Number of distinct video inputs",
                "description": "Some HMDs have 2 separate inputs, one for each eye.",
                "type": "integer",
                "default": 1
              },
              "display_mode": {
                "title": "Display Mode",
                "description": "If a single input is used in side-by-side mode, width and height show the entire width and height of both sides combined.",
                "enum": [
                  "horz_side_by_side",
                  "vert_side_by_side",
                  "full_screen"
                ],
                "default": "horz_side_by_side"
              }
            },
            "required": [
              "width",
              "height",
              "video_inputs",
              "display_mode"
            ]
          }
        },
        "distortion": {
          "title": "HMD Distortion Description",
          "description": "Describes HMD properties related to distortion shader.",
          "type": "object",
          "properties": {
            "k1_red": {
              "title": "K1 Red distortion value",
              "type": "number",
              "default": 0
            },
            "k1_green": {
              "title": "K1 Green distortion value",
              "type": "number",
              "default": 0
            },
            "k1_blue": {
              "title": "K1 Blue distortion value",
              "type": "number",
              "default": 0
            }
          },
          "required": [
            "k1_red",
            "k1_green",
            "k1_blue"
          ]
        },
        "rendering": {
          "title": "HMD Rendering Description (NOT HANDLED)",
          "description": "Describes HMD properties related to rendering. These parameters are not used - please use the per-eye rotate_180 parameter for now",
          "type": "object",
          "properties": {
            "right_roll": {
              "title": "Right eye roll amount (degrees)",
              "type": "number",
              "default": 0
            },
            "left_roll": {
              "title": "Left eye roll amount (degrees)",
              "type": "number",
              "default": 0
            }
          },
          "required": [
            "right_roll",
            "left_roll"
          ]
        },
        "eyes": {
          "title": "HMD Eyes Description",
          "description": "Describes HMD properties related to eyes.",
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "properties": {
              "center_proj_x": {
                "title": "Horizontal center of projection",
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "center_proj_y": {
                "title": "Vertical center of projection",
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "rotate_180": {
                "anyOf": [
                  {
                    "title": "Flip Display Rotation",
                    "description": "Indicates if the view needs to flipped 180 degrees on the z axis (that is, in the plane of the screen) - 1 for true, 0 for false.",
                    "type": "integer",
                    "minimum": 0,
                    "maximum": 1
                  },
                  {
                    "title": "Flip Display Rotation",
                    "description": "Indicates if the view needs to flipped 180 degrees on the z axis (that is, in the plane of the screen)",
                    "type": "boolean",
                    "default": false
                  }
                ]
              }
            },
            "required": [
              "center_proj_y",
              "center_proj_x"
            ]
          }
        }
      },
      "required": [
        "device",
        "field_of_view",
        "resolutions",
        "distortion",
        "rendering",
        "eyes"
      ]
    }
  }
}

